// ============================================================
// Step 1+2: 모의 Tableau 데이터 생성
// ============================================================

const now = new Date();
const yesterday = new Date(now.getTime() - 86400000);
const reportDate = yesterday.toISOString().slice(0, 10);

function rand(min, max) { return Math.round((Math.random() * (max - min) + min) * 10) / 10; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }

const subsidiaries = [
  {
    name: 'A철강(주)',
    segment: '철근 / 단조 / 강관',
    revenue: rand(720, 920),
    prevRevenue: rand(750, 900),
    orders: rand(780, 980),
    prevOrders: rand(800, 960),
    costRatio: rand(0.85, 0.91),
    prevCostRatio: rand(0.84, 0.90),
    scrapPrice: randInt(375, 395),
    prevWeekScrap: randInt(370, 390),
    rebarPrice: randInt(735, 770),
    production: randInt(2400, 2900),
    shipment: randInt(2100, 2700),
    inventory: randInt(7500, 11000),
    operatingRate: rand(55, 75),
  },
  {
    name: 'B철강(주)',
    segment: '철근 / 철강',
    revenue: rand(350, 480),
    prevRevenue: rand(370, 460),
    orders: rand(380, 500),
    prevOrders: rand(400, 490),
    costRatio: rand(0.86, 0.92),
    prevCostRatio: rand(0.85, 0.91),
    scrapPrice: randInt(373, 392),
    prevWeekScrap: randInt(368, 388),
    rebarPrice: randInt(730, 760),
    production: randInt(1200, 1650),
    shipment: randInt(1050, 1500),
    inventory: randInt(4000, 6500),
    operatingRate: rand(48, 70),
  },
  {
    name: 'C산업(주)',
    segment: '와이어로프 / 경강선',
    revenue: rand(155, 210),
    prevRevenue: rand(160, 200),
    orders: rand(170, 220),
    prevOrders: rand(175, 215),
    costRatio: rand(0.79, 0.86),
    prevCostRatio: rand(0.78, 0.85),
    scrapPrice: randInt(370, 390),
    prevWeekScrap: randInt(365, 385),
    rebarPrice: null,
    production: randInt(480, 650),
    shipment: randInt(420, 600),
    inventory: randInt(1800, 2800),
    operatingRate: rand(50, 72),
  },
  {
    name: 'D특수형강(주)',
    segment: '형강 / 특수강',
    revenue: rand(270, 360),
    prevRevenue: rand(280, 350),
    orders: rand(300, 380),
    prevOrders: rand(310, 370),
    costRatio: rand(0.82, 0.88),
    prevCostRatio: rand(0.81, 0.87),
    scrapPrice: randInt(388, 408),
    prevWeekScrap: randInt(383, 403),
    rebarPrice: null,
    production: randInt(900, 1200),
    shipment: randInt(800, 1100),
    inventory: randInt(3000, 4500),
    operatingRate: rand(52, 74),
  },
];

const groupRevenue = subsidiaries.reduce((s, x) => s + x.revenue, 0);
const groupPrevRevenue = subsidiaries.reduce((s, x) => s + x.prevRevenue, 0);
const groupOrders = subsidiaries.reduce((s, x) => s + x.orders, 0);
const groupAvgCost = subsidiaries.reduce((s, x) => s + x.costRatio, 0) / 4;
const groupAvgOp = subsidiaries.reduce((s, x) => s + x.operatingRate, 0) / 4;
const avgScrap = Math.round(subsidiaries.reduce((s, x) => s + x.scrapPrice, 0) / 4);
const avgPsp = Math.round(subsidiaries.reduce((s, x) => s + x.prevWeekScrap, 0) / 4);
const rebarSubs = subsidiaries.filter(x => x.rebarPrice !== null);
const avgRebar = Math.round(rebarSubs.reduce((s, x) => s + x.rebarPrice, 0) / rebarSubs.length);
const spread = avgRebar - avgScrap;
const prevSpread = avgRebar - avgPsp;

return [{
  json: {
    reportDate,
    generatedAt: now.toISOString().slice(0, 16).replace('T', ' '),
    subsidiaries,
    group: {
      revenue: Math.round(groupRevenue * 10) / 10,
      prevRevenue: Math.round(groupPrevRevenue * 10) / 10,
      orders: Math.round(groupOrders * 10) / 10,
      avgCostRatio: Math.round(groupAvgCost * 10000) / 10000,
      avgOperatingRate: Math.round(groupAvgOp * 10) / 10,
      avgScrapPrice: avgScrap,
      prevWeekAvgScrap: avgPsp,
      avgRebarPrice: avgRebar,
      spread,
      prevSpread,
    }
  }
}];

// ============================================================
// Step 3: 보고서 생성 (Slack + HTML Email)
// ============================================================

const data = $input.all()[0].json;
const { reportDate, generatedAt, subsidiaries, group } = data;

function pct(a, b) { return ((a - b) / b * 100).toFixed(1); }
function arr(v) { const n = parseFloat(v); return n > 0 ? '▲' : n < 0 ? '▼' : '-'; }
function sgn(v) { const n = parseFloat(v); return n > 0 ? '+' + v : '' + v; }
function colorVal(v) { const n = parseFloat(v); return n > 0 ? '#e53e3e' : n < 0 ? '#3182ce' : '#333'; }
function colorBg(v) { const n = parseFloat(v); return n > 0 ? '#fff5f5' : n < 0 ? '#ebf8ff' : '#fff'; }

// 이상 감지
const alerts = [];
subsidiaries.forEach(sub => {
  const rc = pct(sub.revenue, sub.prevRevenue);
  const sc = sub.scrapPrice - sub.prevWeekScrap;
  if (sub.costRatio > 0.90) alerts.push({ level: '경고', sub: sub.name, msg: '원가율 ' + (sub.costRatio * 100).toFixed(1) + '% (90% 초과)' });
  if (sub.operatingRate < 55) alerts.push({ level: '주의', sub: sub.name, msg: '가동률 ' + sub.operatingRate + '% (55% 미만)' });
  if (Math.abs(sc) >= 10) alerts.push({ level: '주의', sub: sub.name, msg: '스크랩 단가 전주 대비 ' + (sc > 0 ? '+' : '') + sc + '원/kg 급변동' });
  if (parseFloat(rc) < -10) alerts.push({ level: '경고', sub: sub.name, msg: '매출 전일 대비 ' + rc + '% 급감' });
});
if (group.spread < 350) alerts.push({ level: '긴급', sub: '그룹 전체', msg: '스프레드 ' + group.spread + '천원/톤 (350 미만, 마진 압박)' });

const grpRevChg = pct(group.revenue, group.prevRevenue);
const grpScrapChg = group.avgScrapPrice - group.prevWeekAvgScrap;
const spreadChg = group.spread - group.prevSpread;

// ============================================================
// Slack 보고서 (마크다운)
// ============================================================
let slack = '';
slack += '*KISCO홀딩스 일일 경영 보고서*\n';
slack += '`' + reportDate + '` 전일 마감 실적  |  자동 생성 ' + generatedAt + '\n\n';

slack += '*1. 그룹 종합*\n';
slack += '  합산 매출: *' + group.revenue.toLocaleString() + '백만원* ' + arr(grpRevChg) + ' ' + sgn(grpRevChg) + '% (전일 대비)\n';
slack += '  합산 수주: ' + group.orders.toLocaleString() + '백만원\n';
slack += '  평균 원가율: ' + (group.avgCostRatio * 100).toFixed(1) + '% | 가동률: ' + group.avgOperatingRate + '%\n';
slack += '  스크랩: ' + group.avgScrapPrice + '원/kg ' + arr(grpScrapChg) + (grpScrapChg > 0 ? '+' : '') + grpScrapChg + '원 | 철근: ' + group.avgRebarPrice + '천원/톤\n';
slack += '  스프레드: *' + group.spread + '천원/톤* ' + arr(spreadChg) + (spreadChg > 0 ? '+' : '') + spreadChg + ' (전주 대비)\n\n';

slack += '*2. 계열사별*\n';
subsidiaries.forEach((sub, i) => {
  const rc = pct(sub.revenue, sub.prevRevenue);
  const sc = sub.scrapPrice - sub.prevWeekScrap;
  slack += '  *' + sub.name + '* (' + sub.segment + ')\n';
  slack += '    매출 ' + sub.revenue + '백만원 ' + arr(rc) + sgn(rc) + '% | 원가율 ' + (sub.costRatio * 100).toFixed(1) + '% | 가동률 ' + sub.operatingRate + '%\n';
  slack += '    스크랩 ' + sub.scrapPrice + '원/kg ' + arr(sc) + (sc > 0 ? '+' : '') + sc + '원';
  if (sub.rebarPrice) slack += ' | 철근 ' + sub.rebarPrice + '천원/톤';
  slack += '\n    생산 ' + sub.production + '톤 / 출하 ' + sub.shipment + '톤 / 재고 ' + sub.inventory + '톤\n\n';
});

if (alerts.length > 0) {
  slack += '*3. 이상 감지 (' + alerts.length + '건)*\n';
  alerts.forEach(a => {
    const ic = a.level === '긴급' ? '🚨' : a.level === '경고' ? '⚠️' : '📌';
    slack += '  ' + ic + ' [' + a.level + '] *' + a.sub + '* ' + a.msg + '\n';
  });
} else {
  slack += '*3. 이상 감지*\n  ✅ 금일 이상 감지 항목 없음\n';
}
slack += '\n_Tableau 대시보드 기반 자동 생성 | 데이터브릿지 보안솔루션_';

// ============================================================
// HTML Email 보고서
// ============================================================
let html = '';
html += '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:0;font-family:Apple SD Gothic Neo,Malgun Gothic,sans-serif;background:#f4f5f7;">';
html += '<div style="max-width:680px;margin:20px auto;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);">';

// 헤더
html += '<div style="background:#1a1d2e;padding:28px 32px;">';
html += '<h1 style="color:#00b4a0;margin:0 0 4px 0;font-size:22px;">KISCO홀딩스 일일 경영 보고서</h1>';
html += '<p style="color:#aaa;margin:0;font-size:13px;">기준일: <strong style="color:#fff;">' + reportDate + '</strong> (전일 마감 실적)&nbsp;&nbsp;|&nbsp;&nbsp;자동 생성: ' + generatedAt + '</p>';
html += '</div>';

// 그룹 종합
html += '<div style="padding:24px 32px 16px;">';
html += '<h2 style="color:#1a1d2e;font-size:16px;margin:0 0 16px 0;border-bottom:2px solid #00b4a0;padding-bottom:8px;">1. 그룹 종합 요약</h2>';
html += '<table style="width:100%;border-collapse:collapse;font-size:14px;">';

const grpRows = [
  ['합산 매출', group.revenue.toLocaleString() + '백만원', grpRevChg + '% (전일 대비)', grpRevChg],
  ['합산 수주', group.orders.toLocaleString() + '백만원', '', 0],
  ['평균 원가율', (group.avgCostRatio * 100).toFixed(1) + '%', '', 0],
  ['평균 가동률', group.avgOperatingRate + '%', '', 0],
  ['스크랩 평균', group.avgScrapPrice + '원/kg', (grpScrapChg > 0 ? '+' : '') + grpScrapChg + '원 (전주 대비)', grpScrapChg],
  ['철근 평균', group.avgRebarPrice + '천원/톤', '', 0],
  ['스프레드', group.spread + '천원/톤', (spreadChg > 0 ? '+' : '') + spreadChg + ' (전주 대비)', spreadChg],
];

grpRows.forEach(([label, value, change, raw]) => {
  html += '<tr>';
  html += '<td style="padding:8px 12px;border-bottom:1px solid #eee;color:#666;width:130px;">' + label + '</td>';
  html += '<td style="padding:8px 12px;border-bottom:1px solid #eee;font-weight:bold;color:#1a1d2e;">' + value + '</td>';
  if (change) {
    html += '<td style="padding:8px 12px;border-bottom:1px solid #eee;color:' + colorVal(raw) + ';font-size:13px;">' + arr(raw) + ' ' + change + '</td>';
  } else {
    html += '<td style="padding:8px 12px;border-bottom:1px solid #eee;"></td>';
  }
  html += '</tr>';
});
html += '</table></div>';

// 계열사별 상세
html += '<div style="padding:8px 32px 16px;">';
html += '<h2 style="color:#1a1d2e;font-size:16px;margin:0 0 16px 0;border-bottom:2px solid #00b4a0;padding-bottom:8px;">2. 계열사별 상세</h2>';

subsidiaries.forEach((sub, i) => {
  const rc = pct(sub.revenue, sub.prevRevenue);
  const oc = pct(sub.orders, sub.prevOrders);
  const costDiff = ((sub.costRatio - sub.prevCostRatio) * 100).toFixed(2);
  const sc = sub.scrapPrice - sub.prevWeekScrap;

  html += '<div style="margin-bottom:20px;border:1px solid #e2e8f0;border-radius:6px;overflow:hidden;">';
  html += '<div style="background:#f7fafc;padding:10px 16px;border-bottom:1px solid #e2e8f0;">';
  html += '<strong style="color:#1a1d2e;font-size:14px;">' + (i+1) + '. ' + sub.name + '</strong>';
  html += '<span style="color:#888;font-size:12px;margin-left:8px;">(' + sub.segment + ')</span>';
  html += '</div>';

  html += '<table style="width:100%;border-collapse:collapse;font-size:13px;">';

  // 매출
  html += '<tr><td style="padding:7px 16px;color:#666;width:90px;border-bottom:1px solid #f0f0f0;">매출</td>';
  html += '<td style="padding:7px 16px;font-weight:bold;border-bottom:1px solid #f0f0f0;">' + sub.revenue + '백만원</td>';
  html += '<td style="padding:7px 16px;color:' + colorVal(rc) + ';border-bottom:1px solid #f0f0f0;font-size:12px;">' + arr(rc) + ' ' + sgn(rc) + '% (전일 대비)</td></tr>';

  // 수주
  html += '<tr><td style="padding:7px 16px;color:#666;border-bottom:1px solid #f0f0f0;">수주</td>';
  html += '<td style="padding:7px 16px;font-weight:bold;border-bottom:1px solid #f0f0f0;">' + sub.orders + '백만원</td>';
  html += '<td style="padding:7px 16px;color:' + colorVal(oc) + ';border-bottom:1px solid #f0f0f0;font-size:12px;">' + arr(oc) + ' ' + sgn(oc) + '%</td></tr>';

  // 원가율 / 가동률
  html += '<tr><td style="padding:7px 16px;color:#666;border-bottom:1px solid #f0f0f0;">원가율</td>';
  const crPct = (sub.costRatio * 100).toFixed(1);
  const crColor = sub.costRatio > 0.90 ? '#e53e3e' : '#1a1d2e';
  html += '<td style="padding:7px 16px;font-weight:bold;color:' + crColor + ';border-bottom:1px solid #f0f0f0;">' + crPct + '%</td>';
  html += '<td style="padding:7px 16px;color:' + colorVal(costDiff) + ';border-bottom:1px solid #f0f0f0;font-size:12px;">' + arr(costDiff) + ' ' + (costDiff > 0 ? '+' : '') + costDiff + '%p</td></tr>';

  html += '<tr><td style="padding:7px 16px;color:#666;border-bottom:1px solid #f0f0f0;">가동률</td>';
  const opColor = sub.operatingRate < 55 ? '#e53e3e' : '#1a1d2e';
  html += '<td style="padding:7px 16px;font-weight:bold;color:' + opColor + ';border-bottom:1px solid #f0f0f0;">' + sub.operatingRate + '%</td>';
  html += '<td style="padding:7px 16px;border-bottom:1px solid #f0f0f0;"></td></tr>';

  // 스크랩
  html += '<tr><td style="padding:7px 16px;color:#666;border-bottom:1px solid #f0f0f0;">스크랩</td>';
  html += '<td style="padding:7px 16px;font-weight:bold;border-bottom:1px solid #f0f0f0;">' + sub.scrapPrice + '원/kg</td>';
  html += '<td style="padding:7px 16px;color:' + colorVal(sc) + ';border-bottom:1px solid #f0f0f0;font-size:12px;">' + arr(sc) + ' ' + (sc > 0 ? '+' : '') + sc + '원 (전주 대비)</td></tr>';

  // 철근가 (해당시)
  if (sub.rebarPrice) {
    html += '<tr><td style="padding:7px 16px;color:#666;border-bottom:1px solid #f0f0f0;">철근가</td>';
    html += '<td style="padding:7px 16px;font-weight:bold;border-bottom:1px solid #f0f0f0;">' + sub.rebarPrice + '천원/톤</td>';
    html += '<td style="padding:7px 16px;border-bottom:1px solid #f0f0f0;"></td></tr>';
  }

  // 생산/출하/재고
  html += '<tr><td style="padding:7px 16px;color:#666;">생산/출하</td>';
  html += '<td colspan="2" style="padding:7px 16px;">' + sub.production.toLocaleString() + '톤 / ' + sub.shipment.toLocaleString() + '톤&nbsp;&nbsp;&nbsp;<span style="color:#888;">재고 ' + sub.inventory.toLocaleString() + '톤</span></td></tr>';

  html += '</table></div>';
});
html += '</div>';

// 이상 감지
html += '<div style="padding:8px 32px 24px;">';
html += '<h2 style="color:#1a1d2e;font-size:16px;margin:0 0 16px 0;border-bottom:2px solid #00b4a0;padding-bottom:8px;">3. 이상 감지';
if (alerts.length > 0) html += ' <span style="background:#e53e3e;color:#fff;padding:2px 10px;border-radius:12px;font-size:12px;margin-left:8px;">' + alerts.length + '건</span>';
html += '</h2>';

if (alerts.length > 0) {
  alerts.forEach(a => {
    const bg = a.level === '긴급' ? '#fff5f5' : a.level === '경고' ? '#fffbeb' : '#f0f9ff';
    const border = a.level === '긴급' ? '#e53e3e' : a.level === '경고' ? '#d69e2e' : '#3182ce';
    const icon = a.level === '긴급' ? '🚨' : a.level === '경고' ? '⚠️' : '📌';
    html += '<div style="background:' + bg + ';border-left:4px solid ' + border + ';padding:10px 16px;margin-bottom:8px;border-radius:0 4px 4px 0;font-size:13px;">';
    html += icon + '&nbsp;&nbsp;<strong>[' + a.level + '] ' + a.sub + '</strong>&nbsp;&nbsp;' + a.msg;
    html += '</div>';
  });
} else {
  html += '<div style="background:#f0fff4;border-left:4px solid #38a169;padding:10px 16px;border-radius:0 4px 4px 0;font-size:13px;">✅ 금일 이상 감지 항목 없음</div>';
}
html += '</div>';

// 푸터
html += '<div style="background:#f7fafc;padding:16px 32px;border-top:1px solid #e2e8f0;font-size:11px;color:#999;">';
html += 'Tableau 대시보드 데이터 기반 자동 생성&nbsp;&nbsp;|&nbsp;&nbsp;데이터브릿지 보안솔루션&nbsp;&nbsp;|&nbsp;&nbsp;n8n 자동화 파이프라인';
html += '</div>';

html += '</div></body></html>';

// Email 제목
let emailSubject = '[KISCO] ' + reportDate + ' 일일 경영 보고서';
if (alerts.length > 0) {
  const urgent = alerts.filter(a => a.level === '긴급').length;
  const warn = alerts.filter(a => a.level === '경고').length;
  if (urgent > 0) emailSubject += ' 🚨 긴급 ' + urgent + '건';
  else if (warn > 0) emailSubject += ' ⚠️ 이상감지 ' + alerts.length + '건';
  else emailSubject += ' 📌 참고 ' + alerts.length + '건';
}

return [{
  json: {
    slack_message: slack,
    email_subject: emailSubject,
    email_html: html,
    alerts_count: alerts.length,
    report_date: reportDate,
  }
}];
